'use strict';
(() => {
 const $=id=>document.getElementById(id),dialog=$('socialDialog'),body=$('socialBody');
 const cloud=()=>window.aquariumCloud,game=window.aquariumGame;
 const esc=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
 let screen='friends',data=null,owner=null,working=false,sequence=0,animation=0,serverOffset=0,visitData=null;
 const errors={sign_in_first:'Inicia sesión para jugar con amigos.',session_changed:'La sesión cambió. Vuelve a abrir Amigos.',code_not_found:'No encontramos ese código. Tu amigo debe abrir Amigos para obtener el suyo.',cannot_friend_self:'Ese es tu propio código.',too_many_requests:'Tienes demasiadas solicitudes pendientes. Cancela alguna antes de enviar otra.',friends_only:'Necesitan ser amigos y haber aceptado la solicitud.',not_allowed:'No tienes permiso para esa acción.',visits_disabled:'Tu amigo desactivó las visitas.',no_saved_aquarium:'Tu amigo todavía no tiene una partida guardada en la nube.',choose_1_to_4_friends:'Elige entre uno y cuatro amigos.',expedition_busy:'Ya tienes una expedición pendiente o saliste en las últimas 24 horas.',participant_on_cooldown:'Algún participante ya tiene un premio pendiente o salió en las últimas 24 horas. Esperen o preparen otro grupo.',need_two_players:'Hace falta que al menos un amigo acepte la invitación.',lobby_closed:'La sala ya salió, se canceló o expiró.',expedition_not_finished:'La expedición todavía no terminó.',not_participant:'No participaste en esta expedición.',already_claimed:'Ya recogiste este premio.',save_first:'Primero hay que guardar tu partida en la nube. Comprueba la conexión.',save_busy:'Se está guardando tu partida. Inténtalo de nuevo.',save_conflict:'Hay otra versión de tu partida. Elige cuál continuar en Mi cuenta.',invalid_profile:'Usa un nombre de 2 a 30 caracteres.'};
 function notice(text){const n=$('socialNotice');if(n)n.textContent=text;}
 function show(){if(!dialog.open)dialog.showModal();}
 function shell(title,content){cancelAnimationFrame(animation);animation=0;visitData=null;body.innerHTML=`<div class="social-heading"><span class="eyebrow">TU TRIPULACIÓN</span><h2>${title}</h2><nav class="social-nav"><button id="friendsTab" class="${screen==='friends'?'active':''}">👥 Amigos</button><button id="expeditionsTab" class="${screen==='expeditions'?'active':''}">🛢 Expediciones</button><button id="refreshSocial">↻ Actualizar</button></nav></div><p id="socialNotice" role="status" aria-live="polite"></p>${content}`;$('friendsTab').onclick=()=>open('friends');$('expeditionsTab').onclick=()=>open('expeditions');$('refreshSocial').onclick=()=>open(screen);show();}
 function gate(){shell('El océano se disfruta en compañía','<p>Crea una cuenta o inicia sesión para añadir amigos, visitar sus acuarios y salir de expedición.</p><button id="socialLogin">Entrar a mi cuenta</button>');$('socialLogin').onclick=()=>{dialog.close();cloud()?.openAccount();};}
 async function run(task){if(working)return;working=true;body.setAttribute('aria-busy','true');body.querySelectorAll('button,input,select').forEach(n=>n.disabled=true);try{await task();}catch(e){notice(errors[e.message]||'No se pudo conectar. Tu partida se conserva; pulsa Actualizar para reintentar.');}finally{working=false;body.removeAttribute('aria-busy');body.querySelectorAll('button,input,select').forEach(n=>{if(n.dataset.locked!=='true')n.disabled=false;});}}
 async function load(render=true){const id=cloud()?.identity()?.id;if(!id)return gate();const seq=++sequence;const fresh=await cloud().rpc('aquarium_social_home');if(seq!==sequence||cloud()?.identity()?.id!==id)return;data=fresh;owner=id;serverOffset=Date.parse(data.now)-Date.now();const actionable=data.expeditions.some(e=>e.my_status==='invited'||(!e.claimed&&e.my_status==='accepted'&&e.status==='running'&&Date.parse(e.finishes_at)<=Date.now()+serverOffset))||data.people.some(p=>p.status==='pending'&&p.incoming);$('expeditionBadge').hidden=!actionable;if(render&&dialog.open)screen==='friends'?renderFriends():renderExpeditions();}
 async function open(tab){if(working)return;screen=tab;const id=cloud()?.identity()?.id;if(!id){owner=null;data=null;return gate();}shell(tab==='friends'?'Amigos del arrecife':'El barril de expediciones','<p>Preparando tu tripulación…</p>');await run(()=>load());}
 async function action(name,args,success){await run(async()=>{await cloud().rpc(name,args);await load();if(success)notice(success);});}
 function renderFriends(){const friends=data.people.filter(p=>p.status==='accepted'),requests=data.people.filter(p=>p.status==='pending');
  shell('Amigos del arrecife',`<section class="social-profile"><form id="profileForm"><label>Tu nombre de jugador<input id="playerName" maxlength="30" minlength="2" required value="${esc(data.profile.name)}"></label><label class="social-check"><input id="allowVisits" type="checkbox" ${data.profile.visits?'checked':''}> Permitir que mis amigos visiten mis acuarios</label><button>Guardar perfil</button></form><div><small>COMPARTE ESTE CÓDIGO</small><strong class="friend-code">${esc(data.profile.code)}</strong><p>Tu correo no se muestra. Solo amigos aceptados pueden visitarte.</p></div></section><form id="friendForm" class="friend-search"><label>Código de tu amigo<input id="friendCode" placeholder="AF-XXXXXXXXXXXX" maxlength="20" required autocomplete="off"></label><button>Enviar solicitud</button></form><h3>Solicitudes · ${requests.length}</h3><div id="requestList" class="social-list"></div><h3>Mis amigos · ${friends.length}</h3><div id="friendList" class="social-list"></div>`);
  $('profileForm').onsubmit=e=>{e.preventDefault();const name=$('playerName').value.trim(),visits=$('allowVisits').checked;action('aquarium_profile_update',{p_name:name,p_visits:visits},'Perfil guardado.');};
  $('friendForm').onsubmit=e=>{e.preventDefault();const code=$('friendCode').value.trim();action('aquarium_friend_request',{p_code:code},'Solicitud preparada. Si ya existía, sigue en tu lista.');};
  function row(p,target){const el=document.createElement('article');el.className='social-person';el.innerHTML=`<div><strong>${esc(p.name)}</strong><small>${esc(p.code)} · ${p.status==='accepted'?'Amigo':p.incoming?'Quiere ser tu amigo':'Solicitud enviada'}</small></div><div class="actions"></div>`;const actions=el.querySelector('.actions');function button(text,fn){const b=document.createElement('button');b.textContent=text;b.onclick=fn;actions.append(b);return b;}
   if(p.status==='accepted'){const b=button('Visitar acuario',()=>visit(p.user_id));b.disabled=!p.visits;b.dataset.locked=String(!p.visits);button('Quitar amigo',()=>confirmRemove(p));}
   else {if(p.incoming)button('Aceptar',()=>action('aquarium_friend_action',{p_id:p.id,p_action:'accept'},'¡Ya son amigos!'));button(p.incoming?'Rechazar':'Cancelar solicitud',()=>action('aquarium_friend_action',{p_id:p.id,p_action:'remove'}));}
   target.append(el);
  }
  for(const p of requests)row(p,$('requestList'));for(const p of friends)row(p,$('friendList'));
  if(!requests.length)$('requestList').textContent='No tienes solicitudes pendientes.';if(!friends.length)$('friendList').textContent='Comparte tu código para formar una tripulación.';
 }
 function confirmRemove(p){shell('Quitar amigo',`<p>¿Quieres quitar a ${esc(p.name)} de tus amigos? Dejarán de poder visitar sus acuarios. Las expediciones ya iniciadas conservarán sus participantes.</p><div class="actions"><button id="removeFriend">Quitar amigo</button><button id="keepFriend">Conservar amistad</button></div>`);$('removeFriend').onclick=()=>action('aquarium_friend_action',{p_id:p.id,p_action:'remove'},'Amigo eliminado.');$('keepFriend').onclick=()=>renderFriends();}
 async function visit(id){const seq=sequence;await run(async()=>{const result=await cloud().rpc('aquarium_visit',{p_friend:id});if(!dialog.open||seq!==sequence)return;if(!result?.tanks?.length)throw Error('no_saved_aquarium');shell('De visita con '+esc(result.name),`<p>Estás viendo su última partida guardada. Puedes observar sus peces y decoraciones.</p><label>Acuario<select id="visitTank">${result.tanks.slice(0,5).map((t,i)=>`<option value="${i}">${esc(t.name)}</option>`).join('')}</select></label><canvas id="visitCanvas" class="visit-canvas" width="850" height="520" aria-label="Acuario de tu amigo, solo lectura"></canvas><button id="returnFriends">Volver a amigos</button>`);visitData=result;$('returnFriends').onclick=()=>open('friends');const canvas=$('visitCanvas');const frame=t=>{if(!dialog.open||!canvas.isConnected||!visitData||cloud()?.identity()?.id!==owner)return;game.drawVisit(canvas,visitData.tanks[Number($('visitTank').value)]||visitData.tanks[0],t/1000);animation=requestAnimationFrame(frame);};animation=requestAnimationFrame(frame);});}
 const rewardText=r=>!r?'':r.type==='fish'?(r.species==='fang'?'Colmillo de Plata · pez vampiro':'Guppy leopardo'):r.amount+(r.type==='food'?' porciones de alimento':' monedas');
 function rules(){return `<details class="expedition-rules"><summary>Premios y probabilidades</summary><p>Cada jugador obtiene un premio propio. El servidor sortea una vez al reclamar. Más participantes aumentan el valor de monedas y alimento y las posibilidades de peces.</p><div class="table-scroll"><table><thead><tr><th>Jugadores</th><th>Monedas</th><th>Alimento</th><th>Guppy leopardo</th><th>Pez vampiro</th></tr></thead><tbody>${[[2,65,4,1],[3,62,6,2],[4,58,8,4],[5,54,10,6]].map(([n,coins,fish,vamp])=>`<tr><td>${n}</td><td>${coins}% · ${250+n*50} 🪙</td><td>30% · ${25+n*5} porciones</td><td>${fish}%</td><td>${vamp}%</td></tr>`).join('')}</tbody></table></div><p>Duración: 15 minutos. Una salida por jugador cada 24 horas. Pueden cerrar la página y regresar al terminar. Las salas expiran tras 24 horas. Máximo: cinco jugadores.</p></details>`;}
 function renderExpeditions(){const friends=data.people.filter(p=>p.status==='accepted'),now=Date.now()+serverOffset,cooldown=Date.parse(data.next_departure)>now,blocked=data.expeditions.some(e=>(e.status==='lobby'&&e.host===owner)||(e.status==='running'&&!e.claimed));
  shell('El barril de expediciones',`<div class="expedition-intro"><span class="barrel-art" aria-hidden="true"><i></i></span><div><h3>Rumbo al arrecife misterioso</h3><p>Invita hasta cuatro amigos. Al menos uno debe aceptar antes de zarpar. Todos tendrán su propio premio.</p></div></div>${rules()}<h3>Preparar una expedición</h3>${cooldown?`<p>Tu próxima salida: ${esc(new Date(data.next_departure).toLocaleString('es-MX'))}.</p>`:''}<form id="expeditionForm"><fieldset ${blocked||cooldown?'disabled':''}><legend>Elige entre uno y cuatro amigos</legend>${friends.length?friends.map(p=>`<label class="social-check"><input type="checkbox" name="crew" value="${esc(p.user_id)}"> ${esc(p.name)}</label>`).join(''):'<p>Añade y acepta al menos un amigo para preparar tu primera salida.</p>'}<button ${!friends.length||blocked||cooldown?'disabled data-locked="true"':''}>Invitar a expedición</button></fieldset></form><h3>Salas, viajes y premios</h3><div id="expeditionList" class="social-list"></div><h3>Peces de expedición en reserva</h3><p>Si tu acuario está lleno, tus peces esperan aquí sin perderse.</p><div id="reserveList" class="social-list"></div>`);
  $('expeditionForm').onsubmit=e=>{e.preventDefault();const crew=[...body.querySelectorAll('input[name="crew"]:checked')].map(n=>n.value);if(crew.length<1||crew.length>4)return notice(errors.choose_1_to_4_friends);action('aquarium_expedition_create',{p_friends:crew},'Invitaciones enviadas. Tus amigos pueden aceptarlas desde su barril.');};
  for(const exp of data.expeditions){const done=exp.status==='running'&&Date.parse(exp.finishes_at)<=now,count=exp.members.filter(m=>m.status==='accepted').length,card=document.createElement('article');card.className='expedition-card';card.innerHTML=`<span class="eyebrow">${exp.status==='lobby'?'PREPARANDO SALIDA':exp.claimed?'PREMIO RECOGIDO':done?'EXPEDICIÓN COMPLETADA':'EN EXPEDICIÓN'}</span><h3>Tripulación de ${esc(exp.host_name)}</h3><p>${exp.members.filter(m=>m.status!=='declined').map(m=>esc(m.name)+(m.status==='invited'?' (invitado)':' ✓')).join(' · ')}</p><p>${exp.status==='lobby'?count+'/5 participantes confirmados':exp.claimed?'Tu premio: '+esc(rewardText(exp.reward)):done?'Tu premio está listo.':`Regreso: ${esc(new Date(exp.finishes_at).toLocaleTimeString('es-MX'))} · <strong data-finish="${esc(exp.finishes_at)}"></strong>`}</p><div class="actions"></div>`;const actions=card.querySelector('.actions');const button=(label,fn,disabled=false)=>{const b=document.createElement('button');b.textContent=label;b.onclick=fn;b.disabled=disabled;b.dataset.locked=String(disabled);actions.append(b);};
   const act=kind=>action('aquarium_expedition_action',{p_id:exp.id,p_action:kind});
   if(exp.status==='lobby'){if(exp.host===owner){button('Zarpar con '+count+' jugadores',()=>act('start'),count<2);button('Cancelar expedición',()=>act('cancel'));}else if(exp.my_status==='invited'){button('Aceptar invitación',()=>act('join'));button('Rechazar',()=>act('decline'));}else button('Salir de la sala',()=>act('leave'));}
   else if(done&&!exp.claimed)button('Abrir recompensa',()=>run(async()=>{const reward=await cloud().claimExpedition(exp.id);await load();notice('¡Encontraste '+rewardText(reward)+'!');}));
   $('expeditionList').append(card);
  }
  if(!data.expeditions.length)$('expeditionList').textContent='Aún no tienes viajes. Prepara uno con tus amigos.';
  const reserve=game.reserve();const tanks=game.snapshot().tanks;
  for(const fish of reserve){const card=document.createElement('article');card.className='social-person';card.innerHTML=`<img class="reserve-fish" src="${esc(fish.src)}" alt="${esc(fish.name)}"><div><strong>${esc(fish.name)}</strong><label>Destino<select>${tanks.map((t,i)=>`<option value="${i}">${esc(t.name)} (${t.fish.length}/${8+t.size*4})</option>`).join('')}</select></label></div><button>Recibir pez</button>`;card.querySelector('button').onclick=()=>{if(game.receiveFish(fish.id,Number(card.querySelector('select').value))){renderExpeditions();notice('Pez recibido. El progreso se guardará en tu cuenta.');}};$('reserveList').append(card);}
  if(!reserve.length)$('reserveList').textContent='Los peces que ganes aparecerán aquí.';tickCountdown();
 }
 function tickCountdown(){body.querySelectorAll('[data-finish]').forEach(n=>{const s=Math.max(0,Math.ceil((Date.parse(n.dataset.finish)-Date.now()-serverOffset)/1000));n.textContent=s?Math.floor(s/60)+' min '+s%60+' s':'Listo: pulsa Actualizar para recoger';});}
 $('friends').onclick=()=>open('friends');$('expeditionBarrel').onclick=()=>open('expeditions');
 $('closeSocial').onclick=()=>dialog.close();dialog.addEventListener('close',()=>{cancelAnimationFrame(animation);animation=0;visitData=null;sequence++;});
 setInterval(()=>{tickCountdown();if(owner&&cloud()?.identity()?.id!==owner){owner=null;data=null;$('expeditionBadge').hidden=true;if(dialog.open)gate();}if(dialog.open&&!working&&!visitData&&!body.querySelector('form')?.contains(document.activeElement)&&cloud()?.identity())load(screen==='expeditions').catch(()=>notice('Sin conexión. Pulsa Actualizar para reintentar.'));},30000);
 setInterval(tickCountdown,1000);
})();
